// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CaptureAttempt) predicate.CaptureAttempt {
	return predicate.CaptureAttempt(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CaptureAttempt) predicate.CaptureAttempt {
	return predicate.CaptureAttempt(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CaptureAttempt) predicate.CaptureAttempt {
	return predicate.CaptureAttempt(sql.NotPredicates(p))
}





